def collapse_whitespace(s: str) -> str:
    """Collapse runs of ASCII whitespace into single spaces and strip ends."""
    result = []
    in_space = True
    for ch in s:
        if ch in (' ', '\t', '\n', '\r', '\x0b', '\x0c'):
            if not in_space:
                result.append(' ')
                in_space = True
        else:
            result.append(ch)
            in_space = False
    # Strip leading and trailing spaces
    while result and result[0] == ' ':
        result.pop(0)
    while result and result[-1] == ' ':
        result.pop()
    return ''.join(result)
